/// ABI enum for ResourceOwnership.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum ResourceOwnership {
    /// Borrowed.
    Borrowed = 1,
    /// Owned.
    Owned = 2,
}

impl VmValueCodec for ResourceOwnership {
    fn decode(value: vm::Value) -> RuntimeResult<Self> {
        let raw = <i32 as VmValueCodec>::decode(value)?;
        let decoded = match raw {
            1i32 => Self::Borrowed,
            2i32 => Self::Owned,
            _ => {
                return Err(RuntimeError::from(AbiPlatformError::invalid_argument_value(
                    "value",
                    "unknown ResourceOwnership value",
                ))
                .boxed());
            }
        };
        Ok(decoded)
    }

    fn encode(self) -> vm::Value {
        <i32 as VmValueCodec>::encode(self as i32)
    }
}

impl VmCollectionElement for ResourceOwnership {}

/// Value type for ResourceOwnership.
pub type ResourceOwnershipValue = ResourceOwnership;

impl NativeAbiCodec for ResourceOwnership {
    type Value = ResourceOwnershipValue;

    unsafe fn into_value(self) -> RuntimeResult<<Self as NativeAbiCodec>::Value> {
        Ok(self)
    }

    fn from_value(_binding: &BindingCallContext, value: <Self as NativeAbiCodec>::Value) -> Self {
        value
    }
}

impl VmAbiCodec for ResourceOwnership {
    type Value = ResourceOwnershipValue;

    fn into_value(
        self,
        _context: &vm::ExternalReadContext<'_, '_>,
    ) -> RuntimeResult<<Self as VmAbiCodec>::Value> {
        Ok(self)
    }

    fn from_value(
        _context: &mut vm::ExternalWriteContext<'_, '_>,
        value: <Self as VmAbiCodec>::Value,
    ) -> RuntimeResult<Self> {
        Ok(value)
    }
}

/// Register VM storage schemas for resource.
pub(crate) fn register_resource_vm_storage_types(isolate: &mut vm::Isolate) -> vm::Result<()> {
    isolate.register_named_storage_type("resource::ResourceKind", 1)?;

    Ok(())
}
